<?php /** @var array<string,mixed> $i */ /** @var list<array<string,mixed>> $items */ /** @var array<string,mixed> $bal */ /** @var list<array<string,mixed>> $payments */ /** @var array<string,mixed> $biz */ /** @var int $payable */ /** @var string $today */ /** @var ?array<string,mixed> $manual */ /** @var bool $razorpayOn */ /** @var list<array<string,mixed>> $claims */
$url = '/my/invoices/' . $i['public_id']; $v = static fn (string $k, string $d = ''): string => old($k, $d); $labels = ['issued' => 'Unpaid', 'partially_paid' => 'Partly paid', 'paid' => 'Paid', 'void' => 'Void']; ?>
<div class="page-head"><div><p class="eyebrow">Invoice</p><h1><?= e($i['reference']) ?> · <?= e($i['title']) ?></h1></div><div class="actions"><a class="btn btn-ghost" href="<?= e($url) ?>/pdf">Download PDF</a><a class="btn btn-ghost" href="<?= e($url) ?>/print">Print view</a><a class="btn btn-ghost" href="/my/invoices">&larr; My invoices</a></div></div>
<div class="panel"><div class="detail-grid"><div><span class="muted">Status</span><br><span class="badge badge-bi-<?= e($i['status']) ?>"><?= e($labels[$i['status']] ?? $i['status']) ?></span></div><div><span class="muted">Total</span><br><strong><?= e(money($i['total_minor'])) ?></strong></div>
    <div><span class="muted">Paid</span><br><?= e(money($bal['paid'])) ?></div><div><span class="muted">Balance</span><br><strong><?= e(money($bal['outstanding'])) ?></strong></div><div><span class="muted">Due</span><br><?= $i['due_date'] ? e(local_date($i['due_date'])) : '—' ?><?= $bal['overdue'] ? ' <span class="badge badge-pending">overdue</span>' : '' ?></div></div>
    <?= \Vertex\Core\View::partial('billing-lines', ['items' => $items, 'subtotal' => (int) $i['subtotal_minor'], 'discount' => (int) $i['discount_minor'], 'total' => (int) $i['total_minor'], 'coupon' => (int) $i['coupon_discount_minor'] > 0 ? [$i['coupon_code'], (int) $i['coupon_discount_minor']] : null, 'credited' => (int) $i['credited_minor']]) ?>
    <?php if ($i['client_notes']) : ?><p class="prewrap"><?= e($i['client_notes']) ?></p><?php endif; ?><p class="muted"><?= e($biz['tax_statement'] ?? 'Tax is not applicable.') ?></p></div>
<?php if ($payments !== []) : ?><div class="panel"><h2>Payments received</h2><ul class="plain-list"><?php foreach ($payments as $p) : ?><li><?= e(money(max(0, $p['gross_minor'] - $p['refunded_minor']))) ?> · <?= e(local_date($p['received_on'])) ?> · <?= e($p['reference']) ?> · <a href="/my/receipts/<?= e($p['public_id']) ?>">Receipt</a> · <a href="/my/receipts/<?= e($p['public_id']) ?>/pdf">PDF</a></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($creditNotes !== []) : ?><div class="panel"><h2>Credit notes</h2><ul class="plain-list"><?php foreach ($creditNotes as $n) : ?><li><a href="/my/credit-notes/<?= e($n['public_id']) ?>"><?= e($n['reference']) ?></a> · <?= e(money((int) $n['amount_minor'])) ?> · <?= e($n['reason']) ?><?= $n['status'] === 'void' ? ' (void)' : '' ?> · <a href="/my/credit-notes/<?= e($n['public_id']) ?>/pdf">PDF</a></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if ($payable > 0) : ?><div class="panel"><h2>Pay this invoice</h2>
    <?php $live = \Vertex\Services\RazorpayGateway::liveRequests((int) $i['id']); foreach ($live as $req) : ?><p><a class="btn btn-primary" href="/my/pay/<?= e($req['public_id']) ?>">Pay <?= e(money((int) $req['amount_minor'])) ?> online</a></p>
        <p class="muted">Our team prepared this payment request for exactly <?= e(money((int) $req['amount_minor'])) ?>. We record the payment only after Razorpay confirms it to us.</p><?php endforeach; ?>
    <?php if ($manual !== null) : $upi = (string) $manual['upi_id']; $payee = (string) ($manual['payee_name'] ?? ''); $deep = 'upi://pay?pa=' . rawurlencode($upi) . '&pn=' . rawurlencode($payee !== '' ? $payee : (string) ($biz['trade_name'] ?? '')) . '&am=' . number_format($payable / 100, 2, '.', '') . '&cu=INR&tn=' . rawurlencode('Invoice ' . $i['reference']); ?>
        <div class="upi-box">
            <?php if ($manual['qr_file_id'] !== null) : ?><div class="upi-qr"><img src="/my/upi-qr" alt="UPI QR code of <?= e($payee !== '' ? $payee : (string) ($biz['trade_name'] ?? 'the business')) ?>" width="220" height="220"></div><?php endif; ?>
            <div class="upi-details"><h3>Pay by UPI</h3>
                <p>Amount to pay: <strong><?= e(money($payable)) ?></strong></p>
                <p>UPI ID: <strong class="prewrap"><?= e($upi) ?></strong><?= $payee !== '' ? ' · ' . e($payee) : '' ?></p>
                <div class="copy-row"><input type="text" readonly value="<?= e($upi) ?>" aria-label="UPI ID" data-copy-source><button class="btn btn-ghost btn-sm" type="button" data-copy-button>Copy UPI ID</button></div>
                <p><a class="btn btn-ghost btn-sm" href="<?= e($deep) ?>">Open my UPI app</a> <span class="muted small">(on your phone)</span></p>
                <?php if (!empty($manual['instructions'])) : ?><p class="muted"><?= e($manual['instructions']) ?></p><?php endif; ?>
                <ol class="plain-list"><li>Scan the QR (or use the UPI ID) and pay <strong><?= e(money($payable)) ?></strong>.</li><li>Write down the transaction ID (UTR) your app shows and take a screenshot of the payment.</li><li>Send both below. Our team checks the payment and approves it: the invoice shows as paid after that.</li></ol></div>
        </div>
        <h3>After you have paid</h3>
        <form method="post" action="<?= e($url) ?>/pay" enctype="multipart/form-data" class="form-grid"><?= csrf_field() ?><input type="hidden" name="method" value="upi">
            <div class="field"><label for="am">Amount you paid (₹)</label><input id="am" name="amount" required inputmode="decimal" value="<?= e($v('amount', number_format($payable / 100, 2, '.', ''))) ?>"></div>
            <div class="field"><label for="re">Transaction ID / UTR number</label><input id="re" name="reference" required maxlength="40" value="<?= e($v('reference')) ?>"><p class="hint">From your UPI app: usually 12 digits.</p></div>
            <div class="field"><label for="po">Date you paid</label><input id="po" name="paid_on" type="date" required max="<?= e($today) ?>" value="<?= e($v('paid_on', $today)) ?>"></div>
            <div class="field"><label for="pf">Proof of payment<?= (int) $manual['require_proof'] === 1 ? '' : ' <span class="muted">(optional)</span>' ?></label><input id="pf" name="proof" type="file" accept="image/png,image/jpeg,image/webp,application/pdf"<?= (int) $manual['require_proof'] === 1 ? ' required' : '' ?>><p class="hint">A screenshot of the successful payment (PNG, JPG, WEBP) or a PDF, up to 5 MB.</p></div>
            <div class="form-actions"><button class="btn btn-primary" type="submit">Submit for approval</button></div></form>
    <?php elseif ($live === []) : ?><p class="muted"><?= $razorpayOn ? 'To pay online, ask our team for a payment request: it appears here with a QR for the exact amount.' : 'To pay this invoice, please contact us' ?><?= !empty($biz['payment_instructions']) ? ' or use the payment details on the invoice:' : '.' ?></p><?php if (!empty($biz['payment_instructions'])) : ?><p class="prewrap"><?= e($biz['payment_instructions']) ?></p><?php endif; ?>
    <?php endif; ?></div><?php endif; ?>
<?php if ($claims !== []) : ?><div class="panel"><h2>Your submitted payments</h2><ul class="plain-list"><?php foreach ($claims as $c) : ?><li><?= e($c['reference']) ?> · <?= e(money($c['gross_minor'])) ?> · <?= e(local_date($c['received_on'])) ?> · <span class="badge badge-ps-<?= e($c['status']) ?>"><?= e(['pending_verification' => 'Sent to our team: awaiting approval', 'verified' => 'Approved: payment successful', 'rejected' => 'Not approved', 'reversed' => 'Reversed'][$c['status']] ?? $c['status']) ?></span></li><?php endforeach; ?></ul></div><?php endif; ?>
